WITH matched_keys AS (SELECT id, channel FROM promotions INTERSECT SELECT id, channel FROM promotions WHERE discount_pct BETWEEN 0.31 AND 0.33), verified AS (SELECT s.* FROM promotions s INNER JOIN matched_keys k ON s.id = k.id AND s.channel = k.channel) SELECT CASE WHEN discount_pct >= 0.33 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, promo_code, DATE_TRUNC('MONTH', starts_on) AS activity_month, COUNT(DISTINCT promo_code) AS distinct_promo_codes, COUNT_IF(promo_code = 'VIP') AS vip_events, COUNT(*) AS num_rows, COUNT(*) FILTER (WHERE channel = 'web') AS web_rows, COUNT(*) FILTER (WHERE promo_code = 'WELCOME5') AS welcome5_rows FROM verified GROUP BY discount_pct_tier, promo_code, activity_month;
